import{_ as t,o as e,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"账户与登录","description":"","frontmatter":{},"headers":[],"relativePath":"zh/online/account.md","filePath":"zh/online/account.md","lastUpdated":1792570296000}'),n={name:"zh/online/account.md"};function l(i,a,s,c,g,h){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="账户与登录" tabindex="-1">账户与登录 <a class="header-anchor" href="#账户与登录" aria-label="Permalink to &quot;账户与登录&quot;">​</a></h1><p>在线账户保存你的检索、计量分析、综述、已保存的密钥和积分。自行安装的社区版不需要 PaperSeek 账户。</p><h2 id="注册账户" tabindex="-1">注册账户 <a class="header-anchor" href="#注册账户" aria-label="Permalink to &quot;注册账户&quot;">​</a></h2><ol><li>点击侧栏左下角的 <strong>未登录</strong>，再选择 <strong>注册账户</strong>。</li><li>输入邮箱，发送验证码。</li><li>输入邮件中的六位验证码。</li><li>设置并确认密码。</li></ol><p>密码至少八位；如表单显示其他要求，以界面提示为准。</p><h2 id="登录" tabindex="-1">登录 <a class="header-anchor" href="#登录" aria-label="Permalink to &quot;登录&quot;">​</a></h2><p>可以用邮箱和密码、邮箱验证码，或页面提供的 GitHub、Hugging Face、ModelScope 登录。第三方登录只用于登录 PaperSeek，不代表授权 PaperSeek 使用该平台的模型。</p><p>使用多种登录方式时，请先在 <strong>设置 › 用户</strong> 中核对邮箱和账户 ID。两个不同邮箱的历史并不共享。</p><h2 id="设置-›-用户" tabindex="-1">设置 › 用户 <a class="header-anchor" href="#设置-›-用户" aria-label="Permalink to &quot;设置 › 用户&quot;">​</a></h2><p>从账户菜单的 <strong>账户与积分</strong> 或 <strong>设置</strong> 进入。</p><ul><li><strong>账户</strong>：显示邮箱和账户 ID。ID 默认隐藏，联系支持时可点 <strong>显示</strong> 或 <strong>复制</strong>。账户 ID 不是 API 密钥。</li><li><strong>积分</strong>：显示今日剩余积分、恢复时间和各项任务的消耗，详见<a href="./credits">积分</a>。</li><li><strong>登录方式</strong>：关联或解除关联 GitHub、Hugging Face、ModelScope；没有密码的账户可在这里设置密码。解除关联不会删除历史。</li><li><strong>数据管理</strong>： <ul><li><strong>清空密钥</strong>：删除账户中保存的全部模型连接和数据源密钥，需输入「确认清空密钥」确认。已提交的任务不受影响。</li><li><strong>清空历史</strong>：删除全部检索、计量分析和综述及其导出文件，需输入「清空」确认。正在运行的任务会先被停止，积分扣费记录会保留。此操作无法撤销。</li></ul></li></ul><p>退出登录后，已经在运行的任务仍会继续。</p><h2 id="收不到邮件或密码操作失败" tabindex="-1">收不到邮件或密码操作失败 <a class="header-anchor" href="#收不到邮件或密码操作失败" aria-label="Permalink to &quot;收不到邮件或密码操作失败&quot;">​</a></h2><ul><li>检查垃圾邮件和邮箱拼写。</li><li>使用最新收到的验证码；重新申请可能使旧验证码失效。</li><li>忘记密码时，在登录对话框中选择 <strong>邮箱验证码</strong>。用验证码登录不会更改原密码。</li><li>保存密码失败时，记下页面错误和大致时间后重试。不要把密码或验证码发给任何人，包括客服。</li></ul><p>注册时遇到临时错误，无需重复创建多个账户。更多排查见<a href="./../reference/troubleshooting">常见问题</a>。</p>',15)])])}const u=t(n,[["render",l]]);export{p as __pageData,u as default};
